const ORIGINS = new Set(['https://fsstudiomaker.com.br','https://www.fsstudiomaker.com.br','https://fs-studio-maker.pages.dev']);
const FIELDS = {
  creations: ['id','title','description','category','price','show_price','published','featured','sort_order','translations','created_at','updated_at'],
  creation_images: ['id','creation_id','storage_path','alt_text','sort_order'],
  catalog_categories: ['id','name','slug','translations','sort_order','published','created_at','updated_at'],
  site_media: ['id','title','media_type','storage_path','poster_path','fallback_media_url','fallback_poster_url','alt_text','sort_order','published','created_at','updated_at']
};
const BOOLEAN_FIELDS = new Set(['published','featured','show_price']);
const enc = new TextEncoder();
const json = (data,status=200,headers={}) => new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store',...headers}});
const fail = (message,status=400) => {throw Object.assign(new Error(message),{status})};
async function digest(value){return new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(value)))}
function equal(a,b){if(a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i++)diff|=a[i]^b[i];return diff===0}
async function hmac(secret,value){const key=await crypto.subtle.importKey('raw',enc.encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);return [...new Uint8Array(await crypto.subtle.sign('HMAC',key,enc.encode(value)))].map(b=>b.toString(16).padStart(2,'0')).join('')}
async function validSession(request,env){
  if(!env.ADMIN_PASSWORD||!env.SESSION_SECRET||!env.ADMIN_EMAIL)return false;
  const token=request.headers.get('Cookie')?.match(/(?:^|;\s*)__Host-fs_admin=([^;]+)/)?.[1];
  if(!token)return false;
  const parts=token.split('.');if(parts.length!==3)return false;
  const [expiry,nonce,signature]=parts;if(!/^\d+$/.test(expiry)||Number(expiry)<Date.now()||Number(expiry)>Date.now()+8*3600000||!/^[a-f0-9]{32}$/.test(nonce))return false;
  const expected=await hmac(env.SESSION_SECRET,`${expiry}.${nonce}.${env.ADMIN_EMAIL.toLowerCase()}.${await hmac(env.SESSION_SECRET,env.ADMIN_PASSWORD)}`);
  return equal(enc.encode(signature),enc.encode(expected));
}
function cookie(value,maxAge=28800){return `__Host-fs_admin=${value}; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=${maxAge}`}
async function init(env){
  await env.DB.batch([
    env.DB.prepare('CREATE TABLE IF NOT EXISTS fs_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)'),
    env.DB.prepare('CREATE TABLE IF NOT EXISTS fs_login_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL)')
  ]);
}
function decodeRow(row){const result={...row};for(const key of BOOLEAN_FIELDS)if(key in result)result[key]=!!result[key];if('translations'in result){try{result.translations=JSON.parse(result.translations||'{}')}catch{result.translations={}}}return result}
function valueOf(key,value){if(value===undefined)return null;if(key==='translations')return JSON.stringify(value||{});if(BOOLEAN_FIELDS.has(key))return value?1:0;return value}
function validateRow(table,row){
  if(!row||typeof row!=='object'||Array.isArray(row))fail('Dados inválidos.');
  for(const [key,value] of Object.entries(row)){
    if(!FIELDS[table].includes(key))fail('Campo inválido.');
    if(key==='translations'){if(!value||typeof value!=='object'||JSON.stringify(value).length>20000)fail('Traduções inválidas.');continue}
    if(value!==null&&!['string','number','boolean'].includes(typeof value))fail('Valor inválido.');
    if(typeof value==='string'&&value.length>2000)fail('Texto muito longo.');
    if(typeof value==='number'&&!Number.isFinite(value))fail('Número inválido.');
    if(['storage_path','poster_path','fallback_media_url','fallback_poster_url'].includes(key)&&value&&!safeMediaPath(value))fail('Caminho de mídia inválido.');
  }
  if('title'in row&&(!row.title?.trim()||row.title.length>100))fail('Preencha um título de até 100 caracteres.');
  if('name'in row&&(!row.name?.trim()||row.name.length>60))fail('Preencha o nome da categoria.');
  if(row.price!=null&&row.price<0)fail('Preço inválido.');
  if(row.media_type&&!['image','video'].includes(row.media_type))fail('Tipo de mídia inválido.');
}
function safeMediaPath(path){return typeof path==='string'&&(/^(?:assets\/|\/api\/files\/|uploads\/)/.test(path)||/^https:\/\/(?:fs-studio-maker\.pages\.dev|fsstudiomaker\.com\.br|www\.fsstudiomaker\.com\.br)\//.test(path))&&!path.includes('..')}
function mediaUrl(path){if(!path)return path;if(path.startsWith('uploads/'))return `https://fs-studio-maker.pages.dev/api/files/${path}`;if(path.startsWith('assets/'))return `https://fs-studio-maker.pages.dev/${path}`;return path}
async function rows(env,table,published=false){return (await env.DB.prepare(`SELECT * FROM ${table}${published?' WHERE published = 1':''} ORDER BY sort_order, ${table==='creation_images'?'id':'created_at'}`).all()).results.map(decodeRow)}
async function catalog(env){const products=await rows(env,'creations',true),images=await rows(env,'creation_images');const grouped=new Map();for(const image of images){image.storage_path=mediaUrl(image.storage_path);if(!grouped.has(image.creation_id))grouped.set(image.creation_id,[]);grouped.get(image.creation_id).push(image)}return {products:products.map(item=>({...item,creation_images:grouped.get(item.id)||[]}))}}
async function seed(env){
  const mark=await env.DB.prepare("SELECT value FROM fs_meta WHERE key='seeded'").first();if(mark)return;
  const count=await env.DB.prepare('SELECT count(*) AS n FROM creations').first();if(count.n)fail('O banco já contém produtos. Importação automática cancelada para preservar os dados.',409);
  const statements=[];
  for(const item of SEED.products){
    const row={};for(const key of FIELDS.creations)if(key in item)row[key]=item[key];
    const keys=Object.keys(row);statements.push(env.DB.prepare(`INSERT OR IGNORE INTO creations (${keys.join(',')}) VALUES (${keys.map(()=>'?').join(',')})`).bind(...keys.map(k=>valueOf(k,row[k]))));
    for(const image of item.creation_images||[]){const row={...image,id:image.id||crypto.randomUUID(),creation_id:item.id};const keys=FIELDS.creation_images.filter(k=>k in row);statements.push(env.DB.prepare(`INSERT OR IGNORE INTO creation_images (${keys.join(',')}) VALUES (${keys.map(()=>'?').join(',')})`).bind(...keys.map(k=>valueOf(k,row[k]))))}
  }
  for(const item of SEED.categories){const row={...item,id:item.id||crypto.randomUUID()};const keys=FIELDS.catalog_categories.filter(k=>k in row);statements.push(env.DB.prepare(`INSERT OR IGNORE INTO catalog_categories (${keys.join(',')}) VALUES (${keys.map(()=>'?').join(',')})`).bind(...keys.map(k=>valueOf(k,row[k]))))}
  for(const item of SEED.media){const keys=Object.keys(item);statements.push(env.DB.prepare(`INSERT OR IGNORE INTO site_media (${keys.join(',')}) VALUES (${keys.map(()=>'?').join(',')})`).bind(...keys.map(k=>valueOf(k,item[k]))))}
  statements.push(env.DB.prepare("INSERT OR IGNORE INTO fs_meta (key,value) VALUES ('seeded','1')"));await env.DB.batch(statements);
}
async function query(request,env){
  const input=await request.json(),{table,action='select',filters=[],order=[]}=input;
  if(!Object.hasOwn(FIELDS,table)||!['select','insert','update','delete'].includes(action)||!Array.isArray(filters)||!Array.isArray(order)||filters.length>5||order.length>5)fail('Consulta inválida.');
  const params=[];let where='';
  if(filters.length){where=' WHERE '+filters.map(f=>{if(!FIELDS[table].includes(f.key))fail('Filtro inválido.');params.push(valueOf(f.key,f.value));return `${f.key} = ?`}).join(' AND ')}
  if(action==='select'){
    const sort=order.map(o=>{if(!FIELDS[table].includes(o.key))fail('Ordenação inválida.');return `${o.key} ${o.ascending===false?'DESC':'ASC'}`}).join(',');
    let data=(await env.DB.prepare(`SELECT * FROM ${table}${where}${sort?' ORDER BY '+sort:''} LIMIT 2000`).bind(...params).all()).results.map(decodeRow);
    if(table==='creations'){const images=await rows(env,'creation_images');data=data.map(item=>({...item,creation_images:images.filter(img=>img.creation_id===item.id)}))}
    return json({data:input.single?data[0]||null:data,count:data.length,error:null});
  }
  if(['update','delete'].includes(action)&&(!filters.some(f=>f.key==='id')||filters.length!==1))fail('Identificador obrigatório.');
  if(action==='delete'){
    if(table==='catalog_categories'){const category=await env.DB.prepare('SELECT name FROM catalog_categories'+where).bind(...params).first();if(category){const linked=await env.DB.prepare('SELECT count(*) AS n FROM creations WHERE category=?').bind(category.name).first();if(linked.n)fail('Mova os produtos para outra categoria antes de excluir.',409)}}
    const statements=[];if(table==='creations')statements.push(env.DB.prepare('DELETE FROM creation_images WHERE creation_id=?').bind(filters[0].value));
    statements.push(env.DB.prepare(`DELETE FROM ${table}${where}`).bind(...params));await env.DB.batch(statements);return json({data:null,error:null});
  }
  const row={...input.row};if(action==='insert')row.id=row.id||crypto.randomUUID();validateRow(table,row);
  if(action==='update'&&('id'in row||'created_at'in row))fail('Campo imutável.');
  const keys=Object.keys(row);if(!keys.length)fail('Nenhum campo informado.');
  if(table==='creation_images'&&row.creation_id){const parent=await env.DB.prepare('SELECT id FROM creations WHERE id=?').bind(row.creation_id).first();if(!parent)fail('Produto não encontrado.',404)}
  let statement=action==='insert'?env.DB.prepare(`INSERT INTO ${table} (${keys.join(',')}) VALUES (${keys.map(()=>'?').join(',')})`).bind(...keys.map(k=>valueOf(k,row[k]))):env.DB.prepare(`UPDATE ${table} SET ${keys.map(k=>`${k}=?`).join(',')}${where}`).bind(...keys.map(k=>valueOf(k,row[k])),...params);
  if(table==='catalog_categories'&&action==='update'&&row.name){
    const old=await env.DB.prepare('SELECT name FROM catalog_categories'+where).bind(...params).first();
    await env.DB.batch([statement,env.DB.prepare('UPDATE creations SET category=?, translations=json_remove(translations,\'$.it.category\',\'$.en.category\',\'$.es.category\',\'$.de.category\'),updated_at=CURRENT_TIMESTAMP WHERE category=?').bind(row.name,old?.name||'')]);
  }else await statement.run();
  return json({data:input.single?{id:row.id||filters[0]?.value}:null,error:null});
}
const MEDIA_REPO='joaoeduardocaio-netizen/fs-studio-media';
const MEDIA_TYPES={'jpg':'image/jpeg','png':'image/png','webp':'image/webp','mp4':'video/mp4','webm':'video/webm','mov':'video/quicktime'};
function githubHeaders(env,raw=false){
  const token=String(env.GITHUB_TOKEN||'').trim();
  if(!token)fail('Configure GITHUB_TOKEN nos segredos do Cloudflare.',503);
  if(!/^[A-Za-z0-9_-]+$/.test(token))fail('GITHUB_TOKEN contém espaços ou caracteres inválidos. Cole somente o código gerado pelo GitHub.',503);
  return {'Authorization':`Bearer ${token}`,'User-Agent':'FS-Studio-Admin','Accept':raw?'application/vnd.github.raw+json':'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'};
}
function toBase64(bytes){
  const chunks=[];for(let i=0;i<bytes.length;i+=24576)chunks.push(btoa(String.fromCharCode(...bytes.subarray(i,i+24576))));return chunks.join('');
}
async function githubUpload(request,env){
  const headers=githubHeaders(env);
  const types={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','video/mp4':'mp4','video/webm':'webm','video/quicktime':'mov'};
  const type=request.headers.get('Content-Type'),ext=types[type];if(!ext)fail('Formato não permitido.',415);
  const length=Number(request.headers.get('Content-Length')),limit=8*1024*1024;
  if(!length||length>limit)fail('Envie uma foto ou vídeo de até 8 MB.',413);
  let bytes;try{bytes=new Uint8Array(await request.arrayBuffer())}catch{fail('O envio da foto foi interrompido. Selecione o arquivo novamente.',400)}if(bytes.length!==length||bytes.length>limit)fail('Tamanho inválido.',413);
  const key=`uploads/${crypto.randomUUID()}.${ext}`;
  let body;try{body=JSON.stringify({message:'Adicionar mídia FS Studio Maker',branch:'main',content:toBase64(bytes)})}catch{fail('Falha ao preparar a mídia (UP-PREP).',500)}
  let response;
  for(let attempt=0;attempt<3;attempt++){
    try{response=await fetch(`https://api.github.com/repos/${MEDIA_REPO}/contents/${key}`,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body,redirect:'manual'})}catch{console.error('FS_UPLOAD_NETWORK');fail('Falha na conexão entre Cloudflare e GitHub (UP-NET).',503)}
    if(response.status!==409)break;
    await response.arrayBuffer();
  }
  if(!response.ok){
    console.error('FS_UPLOAD_HTTP',response.status);
    if(response.status===401||response.status===403)fail('O GitHub recusou o acesso. Confira a validade do token e a permissão Contents: Read and write para fs-studio-media.',503);
    if(response.status===404)fail('Crie o repositório fs-studio-media com a branch main e autorize o token para esse repositório.',503);
    if(response.status===409)fail('Outro envio está em andamento. Tente novamente.',409);
    fail('Não foi possível enviar a mídia ao GitHub. Tente novamente.',503);
  }
  if(response.body)await response.body.cancel();return json({data:{path:key},error:null});
}
async function githubMedia(request,env,key){
  const match=key.match(/^uploads\/[a-f0-9-]+\.(jpg|png|webp|mp4|webm|mov)$/);if(!match)fail('Arquivo inválido.',404);
  const cache=globalThis.caches?.default,cacheKey=new Request(request.url,{method:'GET'});
  let cached;try{cached=cache?await cache.match(request):null}catch{console.warn('FS_MEDIA_CACHE_READ')}
  if(cached)return request.method==='HEAD'?new Response(null,{status:cached.status,headers:cached.headers}):cached;
  let upstream;try{upstream=await fetch(`https://api.github.com/repos/${MEDIA_REPO}/contents/${key}?ref=main`,{headers:githubHeaders(env,true),redirect:'manual'})}catch{console.error('FS_MEDIA_NETWORK');fail('Falha na conexão com a mídia (MEDIA-NET).',503)}
  if(!upstream.ok)fail('Não foi possível carregar a mídia.',upstream.status===404?404:503);
  const headers={'Content-Type':MEDIA_TYPES[match[1]],'Cache-Control':'public, max-age=86400, immutable','X-Content-Type-Options':'nosniff'};
  const response=new Response(upstream.body,{status:200,headers});
  // Cache only media bytes. GitHub credentials never enter response headers or cache keys.
  if(cache){try{await cache.put(cacheKey,response.clone());const ranged=await cache.match(request);if(ranged)return request.method==='HEAD'?new Response(null,{status:ranged.status,headers:ranged.headers}):ranged}catch{console.warn('FS_MEDIA_CACHE_WRITE')}}
  return request.method==='HEAD'?new Response(null,{status:200,headers}):response;
}
async function handle(request,env){
  const url=new URL(request.url),path=url.pathname;
  if(!env.DB)fail('Conecte o banco D1 com o nome DB.',503);
  if(path.startsWith('/api/files/')&&['GET','HEAD'].includes(request.method)){
    return githubMedia(request,env,decodeURIComponent(path.slice('/api/files/'.length)));
  }
  if(path.startsWith('/api/public/')&&request.method==='GET'){
    let ready;try{ready=await env.DB.prepare("SELECT value FROM fs_meta WHERE key='seeded'").first()}catch{fail('Importação pendente.',503)}if(!ready)fail('Importação pendente.',503);
    if(path==='/api/public/catalog')return json(await catalog(env));
    if(path==='/api/public/categories')return json(await rows(env,'catalog_categories',true));
    if(path==='/api/public/media')return json((await rows(env,'site_media',true)).map(item=>({...item,storage_path:mediaUrl(item.storage_path),poster_path:mediaUrl(item.poster_path)})));
    fail('Página não encontrada.',404);
  }
  if(request.method!=='GET'){
    if(request.headers.get('Origin')!==url.origin)fail('Origem não autorizada.',403);
    if(request.headers.get('Sec-Fetch-Site')==='cross-site')fail('Origem não autorizada.',403);
    if(path!=='/api/upload'&&!request.headers.get('Content-Type')?.startsWith('application/json'))fail('Formato inválido.',415);
  }
  if(path==='/api/login'&&request.method==='POST'){
    if(!env.ADMIN_EMAIL||!env.ADMIN_PASSWORD||env.ADMIN_PASSWORD.length<12||!env.SESSION_SECRET||env.SESSION_SECRET.length<32)fail('Configure ADMIN_EMAIL, ADMIN_PASSWORD (12 caracteres ou mais) e SESSION_SECRET (32 ou mais) no Cloudflare.',503);
    await init(env);
    const now=Date.now(),ip=await hmac(env.SESSION_SECRET,request.headers.get('CF-Connecting-IP')||'unknown');
    for(const [key,limit] of [[ip,10],['global',100]]){
      const counter=await env.DB.prepare('INSERT INTO fs_login_limits (key,count,reset_at) VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN reset_at<? THEN 1 ELSE count+1 END,reset_at=CASE WHEN reset_at<? THEN excluded.reset_at ELSE reset_at END RETURNING count').bind(key,now+900000,now,now).first();
      if(counter.count>limit)fail('Muitas tentativas. Aguarde 15 minutos.',429);
    }
    const body=await request.json();if(typeof body.email!=='string'||typeof body.password!=='string'||body.password.length>1000)fail('E-mail ou senha incorretos.',401);
    const matches=equal(await digest(body.password),await digest(env.ADMIN_PASSWORD));if(!matches||body.email.trim().toLowerCase()!==env.ADMIN_EMAIL.trim().toLowerCase())fail('E-mail ou senha incorretos.',401);
    await env.DB.prepare('DELETE FROM fs_login_limits WHERE key=?').bind(ip).run();
    await seed(env);
    const expiry=Date.now()+28800000,nonce=crypto.randomUUID().replaceAll('-',''),payload=`${expiry}.${nonce}`,signature=await hmac(env.SESSION_SECRET,`${payload}.${env.ADMIN_EMAIL.toLowerCase()}.${await hmac(env.SESSION_SECRET,env.ADMIN_PASSWORD)}`);
    return json({data:{session:{user:{email:env.ADMIN_EMAIL}}},error:null},200,{'Set-Cookie':cookie(`${payload}.${signature}`)});
  }
  if(path==='/api/session'&&request.method==='GET')return json({data:{session:await validSession(request,env)?{user:{email:env.ADMIN_EMAIL}}:null},error:null});
  if(path==='/api/logout'&&request.method==='POST')return json({error:null},200,{'Set-Cookie':cookie('',0)});
  if(!await validSession(request,env))fail('Entre novamente no painel.',401);
  if(path==='/api/query'&&request.method==='POST')return query(request,env);
  if(path==='/api/upload'&&request.method==='POST')return githubUpload(request,env);
  // Files are retained on removal to keep references safe; catalog records control visibility.
  if(path==='/api/remove-files'&&request.method==='POST')return json({data:[],error:null});
  fail('Rota não encontrada.',404);
}
export default {
  async fetch(request,env){
    const url=new URL(request.url);if(!url.pathname.startsWith('/api/'))return env.ASSETS.fetch(request);
    const origin=request.headers.get('Origin');
    if(request.method==='OPTIONS')return new Response(null,{status:204,headers:ORIGINS.has(origin)?{'Access-Control-Allow-Origin':origin,'Access-Control-Allow-Methods':'GET,HEAD,OPTIONS','Vary':'Origin'}:{}});
    let response;try{response=await handle(request,env)}catch(error){console.error('FS_API_ERROR',new URL(request.url).pathname,error.status||500,error.name||'Error');response=json({error:{message:error.status?error.message:'Não foi possível concluir. Tente novamente.'}},error.status||500)}
    const headers=new Headers(response.headers);if(ORIGINS.has(origin)&&['GET','HEAD'].includes(request.method)){headers.set('Access-Control-Allow-Origin',origin);headers.set('Vary','Origin')}
    headers.set('X-Content-Type-Options','nosniff');return new Response(response.body,{status:response.status,headers});
  }
};
